import React, { useEffect, useState } from "react";
import useApi from "../../../hooks/useApi";
import hospitalsApi from "../../../api/hospitals/hospitalsApi";
import { Flex, Space, Switch, Table } from "antd";
import { toast, ToastContainer } from "react-toastify";
import { CustomForm, CustomFormItem, CustomInput, CustomSelectReactSelect, YesNoModal } from "../../../components";
import { useFormik } from "formik";
import * as Yup from "yup";
import paymentsApi from "../../../api/paymentsApi";
import { useStateContext } from "../../../contexts/ContextProvider";
import retailersApi from "../../../api/retailers/retailersApi";
import RetailInventoryItemModal from "./RetailInventoryItemModal";

export default function RetailPrescriptionsCost() {
    const [showYesNoDialog, setshowYesNoDialog] = useState(false)
    const [prescriptionsList, setprescriptionsList] = useState([]);
    const [prescriptionItemsList, setprescriptionItemsList] = useState([]);
    const [selectedPrescription, setselectedPrescription] = useState();
    const [selectedPrescriptionItem, setselectedPrescriptionItem] = useState();
    const [selectedInventoryItem, setselectedInventoryItem] = useState();
    const [showSubstitutes, setshowSubstitutes] = useState(false)
    const [inventoryList, setinventoryList] = useState([])
    const [updated, setUpdated] = useState(false)
    const { currentColor } = useStateContext()
    const [updateData, setupdateData] = useState()

    const getPrescriptionsListApi = useApi(retailersApi.retailPrescriptionsAction);
    const getPrescriptionsList = async () => {
        await getPrescriptionsListApi.request({
            action: "RetrieveEntityRetailPrescriptions",
        });
    };

    useEffect(() => {
        if (getPrescriptionsListApi.data) {
            if (getPrescriptionsListApi.data.length) {
                setprescriptionsList(getPrescriptionsListApi.data);
            }
        }
        console.log("getPrescriptionsListApi.data", getPrescriptionsListApi.data);
    }, [getPrescriptionsListApi.data]);


    const getInventoryApi = useApi(retailersApi.retailPrescriptionsAction)

    const retrieveRelatedInventoryForProduct = async () => {
        await getInventoryApi.request({
            "action": "GetRelatedEntityInventoryForProduct",
            "product": selectedPrescriptionItem.product

        })
    }

    const retrieveInventoryByProduct = async () => {

        console.log("selectedPrescriptionItem", selectedPrescriptionItem)
        await getInventoryApi.request({
            "action": "GetRelatedEntityInventoryForProduct",
            "product": selectedPrescriptionItem.product

        })

    }

    useEffect(() => {
        if (getInventoryApi.data) {
            if (getInventoryApi.data.length) {
                setinventoryList(getInventoryApi.data)
            } else {
                toast.error("Item is not in stock")
            }

        }
        console.log("getInventoryApi.data", getInventoryApi.data)
    }, [getInventoryApi.data])

    useEffect(() => {

        if (selectedPrescriptionItem) {
            //If item is fully dispensed then do nothing
            if (selectedPrescriptionItem.balance_unit_quanatity > 1) {
                toast.error("This item is fully dispensed")
                return;
            }


            if (showSubstitutes) {
                retrieveRelatedInventoryForProduct();
            } else {
                retrieveInventoryByProduct()
            }
        }
    }, [selectedPrescriptionItem]);



    useEffect(() => {
        getPrescriptionsList();
    }, []);

    //Update prescription item

    const updatePrescriptioItemApi = useApi(retailersApi.retailPrescriptionsAction)

    const updatePrescriptionItem = async (data) => {
        await updatePrescriptioItemApi.request(data)
    }

    useEffect(() => {
        console.log("updatedata", updateData)
        if (updatePrescriptioItemApi.data) {
            if (updatePrescriptioItemApi.data.response_code === 0) {
                getPrescriptionsList()
                toast.success(updatePrescriptioItemApi.data.response_message)

            }
        }

        console.log("updatePrescriptioItemApi.data", updatePrescriptioItemApi.data)
    }, [updatePrescriptioItemApi.data]);

    useEffect(() => {
        console.log("updatedata", updateData)
        if (updateData) {
            updatePrescriptionItem(updateData)
        }
    }, [updateData]);

    const inventoryColumns = [
        {
            title: "Product",
            dataIndex: "product_title",
            render: (text) => <p>{text}</p>,
        },
        {
            title: "Preparation",
            dataIndex: "preparation_title",
            render: (text) => <p>{text}</p>,
        },
        {
            title: "In Stock (Units)",
            dataIndex: "current_unit_quantity",
        },
    ];


    const orderItemColumns = [
        {
            title: "Product",
            dataIndex: "entity_sub_store_receipt_title",
            render: (text) => <p>{text}</p>,
        },
        {
            title: "Preparation",
            dataIndex: "entity_sub_store_receipt_preparation_title",
            render: (text) => <p>{text}</p>,
        },
        {
            title: "Required",
            dataIndex: "required_unit_quantity",
        },
        {
            title: "Ordered",
            dataIndex: "issued_unit_quantity",
        },
        {
            title: "Cost (KES)",
            dataIndex: "item_total_price",
        },
        {
            title: "Date",
            dataIndex: "created",
        },
    ];

    const prescriptionColumns = [
        {
            title: "Patient",
            dataIndex: "patient_title",
            render: (text) => <p>{text}</p>,
        },
        {
            title: "Prescriber",
            dataIndex: "prescriber_name",
            render: (text) => <p>{text}</p>,
        },
        {
            title: "Date",
            dataIndex: "created",
        },
    ];
    const prescriptionItemColumns = [

        {
            title: "Brand",
            dataIndex: "product_title",
            render: (text) => <p>{text}</p>,
        },
        {
            title: "Route",
            dataIndex: "route_title",
            render: (text) => <p>{text}</p>,
        },
        {
            title: "Dose",
            dataIndex: "dose",
            render: (text) => <p>{text}</p>,
        },

        {
            title: "Frequency",
            dataIndex: "frequency_title",
        },
        {
            title: "Days",
            dataIndex: "days",
        },
        {
            title: "Instruction",
            dataIndex: "instruction",
        },
        {
            title: "Required",
            dataIndex: "required_unit_quantity",
        },
        {
            title: "Issued",
            dataIndex: "issued_unit_quantity",
        },
        {
            title: "Balance",
            dataIndex: "balance_unit_quantity",
        },
    ];

    const [selectedPrescriptionRowKeys, setSelectedPrescriptionRowKeys] = useState([]);
    const [selectedPrescriptionItemRowKeys, setSelectedPrescriptionItemRowKeys] = useState([]);
    const [selectedInventoryRowKeys, setSelectedInventoryRowKeys] = useState([]);
    const [openInventoryModal, setopenInventoryModal] = useState(false)
    const [currentPrescriptionOrder, setcurrentPrescriptionOrder] = useState()
    const [paymentMethods, setpaymentMethods] = useState([])

    const [selectedPaymentMethod, setselectedPaymentMethod] = useState()
    const [mobileMoneyNumber, setmobileMoneyNumber] = useState()


    //Prescription Row Selection
    const onPrescriptionSelectChange = (newSelectedRowKeys, selectedRow) => {
        setselectedPrescription(selectedRow[0]);
        setSelectedPrescriptionRowKeys(newSelectedRowKeys);




        //Reset selected inventory item
        setselectedInventoryItem(null)
        setSelectedInventoryRowKeys([])
        setinventoryList([])

        //Reset selected prescription item
        setselectedPrescriptionItem(null)
        setSelectedPrescriptionItemRowKeys([])
        setprescriptionItemsList([])
    };

    const prescriptionRowSelection = {
        selectedRowKeys: selectedPrescriptionRowKeys,
        onChange: onPrescriptionSelectChange,
    };


    //Prescription Item  Row Selection

    const onPrescriptionItemSelectChange = (newSelectedRowKeys, selectedRow) => {
        if (parseInt(selectedRow[0]["balance_unit_quantity"]) < 1 && parseInt(selectedRow[0]["required_unit_quantity"]) > 0 && parseInt(selectedRow[0]["issued_unit_quantity"]) === parseInt(selectedRow[0]["required_unit_quantity"])) {
            toast.error("This prescription item is fully dispensed")
            return;
        }
        setselectedPrescriptionItem(selectedRow[0]);
        setSelectedPrescriptionItemRowKeys(newSelectedRowKeys);
        setinventoryList([])
        setselectedInventoryItem(null)
        setSelectedInventoryRowKeys([])
    };



    const prescriptionItemRowSelection = {
        selectedRowKeys: selectedPrescriptionItemRowKeys,
        onChange: onPrescriptionItemSelectChange,
    };



    //Inventory Item Row Selection
    const onInventoryItemSelectChange = (newSelectedRowKeys, selectedRow) => {
        setselectedInventoryItem(selectedRow[0]);
        setSelectedInventoryRowKeys(newSelectedRowKeys);
        // setinventoryList([])
    };
    const inventoryItemRowSelection = {
        selectedRowKeys: selectedInventoryRowKeys,
        onChange: onInventoryItemSelectChange,
    };





    //Get or create an open order for selected prescription
    const getOrCreatePrescriptionOrderApi = useApi(hospitalsApi.hospitalStaffAction)
    const getOrCreatePrescriptionOrder = async () => {
        await getOrCreatePrescriptionOrderApi.request({
            "action": "GetOrCreatePrescriptionOrder",
            "entity_sub_store": selectedPrescription.entity_sub_store,
            "hospital_prescription": selectedPrescription.id
        })
    }
    useEffect(() => {
        if (getOrCreatePrescriptionOrderApi.data) {

            if (getOrCreatePrescriptionOrderApi.data.prescription_order) {
                toast.success(getOrCreatePrescriptionOrderApi.data.response_message)
                setcurrentPrescriptionOrder(getOrCreatePrescriptionOrderApi.data.prescription_order)
            }

        }
        console.log("getOrCreatePrescriptionOrderApi.data", getOrCreatePrescriptionOrderApi.data)
    }, [getOrCreatePrescriptionOrderApi.data]);

    //When new prescription is selected
    useEffect(() => {
        if (selectedPrescription) {

            setprescriptionItemsList(selectedPrescription.items)
            getOrCreatePrescriptionOrder()
            console.log("seLEcted ", selectedPrescription)
        }
    }, [selectedPrescription]);


    const handleSwitching = (e) => {
        if (e === true) {
            setshowSubstitutes(true)
        } else {
            setshowSubstitutes(false)
        }
    }



    useEffect(() => {
        if (selectedInventoryItem) {
            setopenInventoryModal(true)
        }
    }, [selectedInventoryItem])


    useEffect(() => {
        if (updated) {
            getOrCreatePrescriptionOrder()
        }
    }, [updated])

    const prescriptionFormik = useFormik({
        initialValues: {
            payment_method: "",
            mobile_money_number: "",
        },

        validationSchema: Yup.object({
            payment_method: Yup.object().required("Select destination pharmacy"),
        }),
        onSubmit: (values, { resetForm }) => {
            //Dispatch action

            console.log("VALZ", values);
            setshowYesNoDialog(true)
            setselectedPaymentMethod(values.payment_method)
            setmobileMoneyNumber(values.mobile_money_number)


            resetForm();
        },
    });

    const paymentMethodsApi = useApi(paymentsApi.paymentMethodsAction)

    const getPaymentMethods = async () => {
        await paymentMethodsApi.request({
            "action": "GetAllPaymentMethods"
        })
    }


    useEffect(() => {
        if (paymentMethodsApi.data) {
            if (paymentMethodsApi.data.length) {
                setpaymentMethods(paymentMethodsApi.data.map((i) => ({
                    label: i.title,
                    value: i.id,
                })))
            }
        }

    }, [paymentMethodsApi.data])



    useEffect(() => {
        getPaymentMethods();
    }, [])

    const closePrescriptionApi = useApi(hospitalsApi.hospitalStaffAction)

    const handleClosePrescriptionOrder = async () => {
        setshowYesNoDialog(false)
        await closePrescriptionApi.request({
            "action": "ClosePrescriptionOrder",
            "prescription_order": currentPrescriptionOrder.id,
            "payment_method": selectedPaymentMethod.value,
            "mobile_money_number": mobileMoneyNumber

        })

    }
    const [errors, setErrors] = useState();

    useEffect(() => {
        if (errors && errors.length) {
            errors.map((x) => {
                toast.error(x);
            });
        }
    }, [errors]);

    useEffect(() => {
        if (closePrescriptionApi.data) {

            if (closePrescriptionApi.data.prescription_order) {
                toast.success(closePrescriptionApi.data.response_message)
            }
            if (closePrescriptionApi.data.errors) {
                setErrors(closePrescriptionApi.data.errors)
            }

        }
        console.log("closePrescriptionApi.data", closePrescriptionApi.data)
    }, [closePrescriptionApi.data])

    return (<div className="grid grid-cols-1 md:grid-cols-12 my-14">

        <div
            className="max-h-[720px] bg-gray-100 overflow-y-scroll col-span-3 border-2 border-gray-300 rounded-md overflow-x-hidden "
        >
            <ToastContainer theme="colored" position="bottom-center" />
            {showYesNoDialog && <YesNoModal yesAction={handleClosePrescriptionOrder} content={"This action is reversible. You can always create a new order for a prescription"} title={"Close Prescription Order"} showModal={showYesNoDialog} setShowModal={setshowYesNoDialog} />}
            {openInventoryModal && <RetailInventoryItemModal updateData={updateData} setupdateData={setupdateData} currentPrescriptionOrder={currentPrescriptionOrder} openInventoryModal={openInventoryModal} setopenInventoryModal={setopenInventoryModal} selectedInventoryItem={selectedInventoryItem} selectedPrescriptionItem={selectedPrescriptionItem} selectedprte selectedPrescription={selectedPrescription} updated={updated} setUpdated={setUpdated} />}
            <h1 className="text-center font-semibold text-xl">Prescriptions</h1>
            <Table
                rowSelection={{
                    type: "radio",
                    ...prescriptionRowSelection,
                }}
                columns={prescriptionColumns}
                dataSource={prescriptionsList}
            />
        </div>
        <div className="max-h-[720px] bg-gray-300 overflow-y-scroll col-span-6 border-5 border-gray-300 rounded-md overflow-x-hidden">

            {selectedPrescription ? <div className="grid grid-cols-2 md:grid-cols-4 bg-white border-2 border-gray-400 rounded-md mx-2">
                <div className=" border-1 border-gray-300 p-2">
                    <p>Name</p>
                    <p>{selectedPrescription.patient_title}</p>
                </div>
                <div className=" border-1 border-gray-300 p-2">
                    <p>Gender</p>
                    <p>{selectedPrescription.patient_gender}</p>
                </div>
                <div className=" border-1 border-gray-300 p-2">
                    <p>Date of Birth</p>
                    <p>{selectedPrescription.patient_date_of_birth}</p>
                </div>
                <div className=" border-1 border-gray-300 p-2">
                    <p>Age</p>
                    <p>{selectedPrescription.patient_age} Years</p>
                </div>
            </div> : <div></div>}


            <h1 className="text-center font-semibold text-xl">Prescription Items</h1>

            <Table
                rowSelection={{
                    type: "radio",
                    ...prescriptionItemRowSelection,
                }}
                columns={prescriptionItemColumns}
                dataSource={prescriptionItemsList}
            />
            {currentPrescriptionOrder ? <div>
                <h1 className="text-center font-semibold text-xl">Order Items</h1>
                <div className="grid grid-cols-1 md:grid-cols-4 items-center">
                    {currentPrescriptionOrder && currentPrescriptionOrder.items ? <div className="rounded-sm b" >
                        <p className="text-2xl">KES <span>{currentPrescriptionOrder.items
                            .reduce((acc, item) => acc + parseFloat(item.item_total_price), 0).toFixed(2)
                        }</span></p></div> : <div></div>}
                    <div className="col-span-3">
                        <CustomForm
                            layout="horizontal"
                            handleFinish={prescriptionFormik.handleSubmit}
                            className="grid grid-cols-1 md:grid-cols-3 gap-2 w-full "
                        >
                            <CustomFormItem
                                className="w-full h-14"
                                touched={prescriptionFormik.touched.payment_method}
                                error={prescriptionFormik.errors.payment_method}
                            >
                                <CustomSelectReactSelect
                                    className="text-start w-full h-full"
                                    name="payment_method"
                                    id="payment_method"
                                    label="Select payment method"
                                    size="large"
                                    onChange={(value) =>
                                        prescriptionFormik.setFieldValue(
                                            "payment_method",
                                            value
                                        )
                                    }
                                    value={prescriptionFormik.values.payment_method}
                                    placeholder="Select payment method"
                                    options={paymentMethods}
                                />
                            </CustomFormItem>
                            {prescriptionFormik.values.payment_method.label === "MOBILE MONEY" ? <CustomFormItem
                                className="w-full"
                                touched={prescriptionFormik.touched.mobile_money_number}
                                error={prescriptionFormik.errors.mobile_money_number}
                            >
                                <CustomInput
                                    id="mobile_money_number"
                                    name="mobile_money_number"
                                    onChange={prescriptionFormik.handleChange}
                                    placeholder="Enter mobile money number"
                                    label="Enter mobile money number"
                                    size="large"
                                    type="phone"
                                    value={prescriptionFormik.values.mobile_money_number}
                                />
                            </CustomFormItem> : <div></div>}

                            <button
                                onClick={prescriptionFormik.handleSubmit}
                                id="formikPrescription"
                                style={{ background: currentColor }}
                                className="w-full h-12 my-auto rounded-md m-auto text-white self-center flex-1"
                                color="primary"
                                type="submit"
                            >
                                Confirm and Close
                            </button>
                        </CustomForm>
                    </div>

                </div>
                <Table
                    rowSelection={{
                        type: "radio",
                        ...prescriptionItemRowSelection,
                    }}
                    columns={orderItemColumns}
                    dataSource={currentPrescriptionOrder.items}
                />

            </div> : <div></div>}
        </div>
        <div className="max-h-[720px] bg-gray-300 overflow-y-scroll col-span-3 border-5 border-gray-300 rounded-md overflow-x-hidden">

            {/**  <div className=" w-full">
          <h1 className="text-center font-semibold text-xl">Stock Inventory</h1>
          <div className="w-full grid grid-cols-2" >
            <p>Show Substitutes</p>

            <Switch

              onChange={(e) => handleSwitching(e)}
              checkedChildren="No"
              unCheckedChildren="Yes"
              defaultChecked
            />
          </div>
        </div>*/}
            <Table
                rowSelection={{
                    type: "radio",
                    ...inventoryItemRowSelection,
                }}
                columns={inventoryColumns}
                dataSource={inventoryList}
            />
        </div>

    </div>
    );
}
